// Iteramos sobre todos los pacientes que entraron desde Internación
const ordenesLimpias = $input.all().map(item => {
  const data = item.json;

  // 1. Extraer datos de los objetos anidados para no repetir código
  const paciente = data.patient_data || {};
  const orden = data.clinical_order || {};

  const nombre = paciente.first_name || "";
  const apellido = paciente.last_name || "";

  // 2. Generar el seudónimo para Telegram (ej: "M.G.")
  const iniciales = `${nombre.charAt(0) || 'X'}.${apellido.charAt(0) || 'X'}.`;

  // 3. Formatear la fecha de nacimiento (viene separada en year, month, day)
  const bd = paciente.birth_date || {};
  const fechaNac = bd.year ? `${bd.year}-${bd.month}-${bd.day}` : "";

  // 4. Mapear el nivel de urgencia (viene como un booleano true/false)
  const prioridad = data.is_urgent ? "Urgente" : "Rutina";

  // 5. Armar la ubicación combinando sector, habitación y cama
  const ubicacion = `${orden.sector || 'S/D'} - Hab: ${orden.room || '-'} Cama: ${orden.bed || '-'}`;

  // 6. Retornar el objeto plano respetando el Contrato de Datos base
  return {
    id_orden: data.request_id,
    origen: "INTERNACION",
    modalidad: orden.modality,
    estudio: orden.procedure,
    diagnostico: orden.diagnosis,
    observaciones: orden.observations || "Sin observaciones",
    ubicacion: ubicacion,
    paciente_nombre: nombre,
    paciente_apellido: apellido,
    paciente_seudonimo: iniciales,
    paciente_dni: paciente.national_id,
    fecha_nacimiento: fechaNac,
    medico_solicitante: "Médico de Planta", // El mock de internación no traía un campo de médico específico
    prioridad_solicitada: prioridad,
    is_active: true
  };
});

// Retornamos la estructura que n8n necesita para seguir el flujo
return ordenesLimpias.map(orden => ({ json: orden }));

// Iteramos sobre todos los pacientes que entraron desde la Guardia
const ordenesLimpias = $input.all().map(item => {
  const data = item.json;

  // 1. Limpiar el formato del nombre (Viene como "Apellido, Nombre")
  const partesNombre = (data.nom_paciente || "").split(', ');
  const apellido = partesNombre[0] || "";
  const nombre = partesNombre[1] || "";

  // 2. Generar el seudónimo para Telegram (ej: "J.P.")
  const iniciales = `${nombre.charAt(0) || 'X'}.${apellido.charAt(0) || 'X'}.`;

  // 3. Mapear el nivel de urgencia
  const prioridad = data.urgente === "SI" ? "Urgente" : "Rutina";

  // 4. Retornar el objeto plano respetando el Contrato de Datos base
  return {
    id_orden: data.id_transaccion,
    origen: "GUARDIA",
    modalidad: data.modalidad || "Sin modalidad asignada",
    estudio: data.estudio_req || "Sin estudio",
    diagnostico: data.diagnostico || "Sin diagnostico",
    observaciones: data.observaciones || "Sin observaciones",
    paciente_nombre: nombre,
    paciente_apellido: apellido,
    paciente_seudonimo: iniciales,
    paciente_dni: data.doc_identidad || "Sin DNI",
    fecha_nacimiento: data.fecha_nacimiento || "Sin fecha de nacimiento",
    medico_solicitante: data.solicitante || "Solicitante no especificado",
    prioridad_solicitada: prioridad,
    is_active: true
  };
});

// Retornamos la estructura que n8n necesita para seguir el flujo
return ordenesLimpias.map(orden => ({ json: orden }));

// Iteramos sobre todos los pacientes ambulatorios
const ordenesLimpias = $input.all().map(item => {
  const data = item.json;

  // 1. Desarmar el formato DICOM del nombre (APELLIDO^NOMBRE)
  const partesNombre = (data.PACIENTE_DATA || "").split('^');
  const apellido = partesNombre[0] || "";
  const nombre = partesNombre[1] || "";

  // 2. Generar el seudónimo para Telegram (ej: "R.R.")
  const iniciales = `${nombre.charAt(0) || 'X'}.${apellido.charAt(0) || 'X'}.`;

  // 3. Inferir modalidad DICOM basándonos en el texto de la prestación
  let modalidadInferida = "OTRO";
  const prestacion = (data.PRESTACION_DESC || "").toLowerCase();

  if (prestacion.includes("resonancia")) modalidadInferida = "MR";
  else if (prestacion.includes("ecografia") || prestacion.includes("ecografía")) modalidadInferida = "US";
  else if (prestacion.includes("tomografia") || prestacion.includes("tomografía")) modalidadInferida = "CT";
  else if (prestacion.includes("radiografia") || prestacion.includes("radiografía")) modalidadInferida = "CR";

  // 4. Retornar el objeto plano respetando el Contrato de Datos base
  return {
    id_orden: data.ID_CITA,
    origen: "AMBULATORIO", 
    modalidad: modalidadInferida,
    estudio: data.PRESTACION_DESC,
    diagnostico: data.DIAGNOSTICO || "Sin especificar",
    observaciones: data.OBSERVACIONES || "Sin observaciones",
    ubicacion: "Atención Ambulatoria", // Sector genérico para no dejarlo vacío
    paciente_nombre: nombre,
    paciente_apellido: apellido,
    paciente_seudonimo: iniciales,
    paciente_dni: data.NRO_DOCUMENTO,
    fecha_nacimiento: data.FECHA_NACIMIENTO,
    medico_solicitante: data.MEDICO_DERIVANTE,
    prioridad_solicitada: "RUTINA", // Los ambulatorios son rutina por defecto
    is_active: true
  };
});

// Retornamos la estructura que n8n necesita para seguir el flujo
return ordenesLimpias.map(orden => ({ json: orden }));
